# এসএসসি সাধারণ গণিত অধ্যায় ২: সমন্বিত সৃজনশীল প্রশ্ন (২.১ সেট + ২.২ অন্বয় ও ফাংশন), ১০টি; ক (২), খ (৪), গ (৪)
# gen_cq_c10_2.py এটি import করে একই ফাইলে (cq_c10_2.json) b11–b20 হিসেবে যোগ করে।
import sympy as sp
from fractions import Fraction as F
x,y=sp.symbols('x y')
P=lambda X,Y:{(p,q) for p in X for q in Y}

# ---------- যাচাই ----------
A={n for n in range(1,10) if n*n<10}; B={n for n in range(-5,6) if n*n-3*n+2==0}
R=sorted((p,q) for p,q in P(A,B) if p+q==4); assert A=={1,2,3} and B=={1,2} and len(P(A,B))==6 and R==[(2,2),(3,1)] and sorted((q,p) for p,q in R)==[(1,3),(2,2)]
f=lambda t:t*t-4*t+3; A={1,3}; B={1,2,3}; assert {t for t in range(-9,10) if f(t)==0}==A and P(A,B)&P(B,A)==P(A&B,A&B) and len(P(A&B,A&B))==4 and {f(t) for t in B}=={-1,0} and f(1)==f(3)
f=lambda t:2*t-3; A={-1,0,1,2}; FA={f(t) for t in A}; assert FA=={-5,-3,-1,1} and A&FA=={-1,1} and sp.solve(2*x-3-5,x)==[4]
assert 50-10==40 and 30+25-40==15 and (30-15,25-15)==(15,10) and {15,10,15}=={10,15}
Fx=(3*x+2)/(2*x-3); assert Fx.subs(x,0)==F(-2,3) and Fx.subs(x,1)==-5 and sp.simplify(Fx.subs(x,Fx)-x)==0
Bv=[Fx.subs(x,t) for t in [-2,-1,0,1,2]]; assert Bv==[sp.Rational(4,7),sp.Rational(1,5),sp.Rational(-2,3),-5,8] and not ({-2,-1,0,1,2}&set(Bv))
A={3,4,5,6}; R=sorted((p,p+1) for p in A if p+1 in A); assert R==[(3,4),(4,5),(5,6)] and {p for p,_ in R}&{q for _,q in R}=={4,5}
U=set(range(1,13)); A={d for d in U if 12%d==0}; B={d for d in U if d%3==0}; assert A=={1,2,3,4,6,12} and B=={3,6,9,12} and A-B==A&(U-B)=={1,2,4} and {t//3 for t in B}=={1,2,3,4}<=A
A={-2,-1,0,1,2}; S=sorted((t,t*t+1) for t in A); Bs={q for _,q in S}; assert Bs=={1,2,5} and A&Bs=={1,2} and A-Bs=={-2,-1,0} and len(P(A&Bs,A-Bs))==6
g=x**3-4*x; assert set(sp.solve(g,x))=={-2,0,2} and sp.expand(g.subs(x,-x)+g)==0 and g.subs(x,1)+g.subs(x,-1)==0
A={-2,0,2}; B={-1,0,1}; assert A|B=={-2,-1,0,1,2} and A&B=={0} and (A|B)-(A&B)=={-2,-1,1,2} and 2**4==16
a,b=sp.symbols('a b'); assert sp.solve([a+b-5,3*a+b-11],[a,b])=={a:3,b:2} and sp.solve(3*x+2-14,x)==[4]
A={n for n in range(1,30) if 3*n+2<20}; Bf={3*n+2 for n in A}; assert A=={1,2,3,4,5} and Bf=={5,8,11,14,17} and A&Bf=={5} and len(A)*len(Bf)==25

CQ=[
("A = {x ∈ ℕ : x² < 10}, B = {x ∈ ℤ : x² − 3x + 2 = 0} এবং R = {(x, y) : x ∈ A, y ∈ B এবং x + y = 4}।",
 ["A ও B কে তালিকা পদ্ধতিতে প্রকাশ কর।","A × B নির্ণয় কর এবং R কে তালিকা পদ্ধতিতে প্রকাশ কর।","R এর ডোমেন ও রেঞ্জ নির্ণয় কর এবং R⁻¹ নির্ণয় করে R⁻¹ একটি ফাংশন কি না যাচাই কর।"],
 "ক) x² < 10 ⇒ x = 1, 2, 3 ⇒ A = {1, 2, 3}\nx² − 3x + 2 = (x − 1)(x − 2) = 0 ⇒ B = {1, 2}\nখ) A × B = {(1, 1), (1, 2), (2, 1), (2, 2), (3, 1), (3, 2)}\nx + y = 4 শর্ত মানে: R = {(2, 2), (3, 1)}\nগ) ডোম R = {2, 3}, রেঞ্জ R = {1, 2}\nR⁻¹ = {(2, 2), (1, 3)}\nR⁻¹ এর প্রতিটি প্রথম উপাদান (2 ও 1) একবার করে আছে ⇒ R⁻¹ একটি ফাংশন",'মধ্যম'),
("f(x) = x² − 4x + 3, A = {x ∈ ℝ : f(x) = 0} এবং B = {x ∈ ℕ : x < 4}।",
 ["A ও B কে তালিকা পদ্ধতিতে প্রকাশ কর।","দেখাও যে, (A × B) ∩ (B × A) = (A ∩ B) × (A ∩ B)","B সেটে f এর রেঞ্জ নির্ণয় কর এবং B এর উপর f এক-এক ফাংশন কি না যাচাই কর।"],
 "ক) x² − 4x + 3 = (x − 1)(x − 3) = 0 ⇒ A = {1, 3}; B = {1, 2, 3}\nখ) A × B = {(1, 1), (1, 2), (1, 3), (3, 1), (3, 2), (3, 3)}\nB × A = {(1, 1), (1, 3), (2, 1), (2, 3), (3, 1), (3, 3)}\n(A × B) ∩ (B × A) = {(1, 1), (1, 3), (3, 1), (3, 3)}\nA ∩ B = {1, 3} ⇒ (A ∩ B) × (A ∩ B) = {(1, 1), (1, 3), (3, 1), (3, 3)} ∴ সমান\nগ) f(1) = 0, f(2) = −1, f(3) = 0 ⇒ রেঞ্জ = {−1, 0}\nf(1) = f(3) = 0 কিন্তু 1 ≠ 3 ⇒ f এক-এক নয়",'কঠিন'),
("f(x) = 2x − 3 এবং A = {−1, 0, 1, 2}।",
 ["f(A) = {f(x) : x ∈ A} নির্ণয় কর।","S = {(x, y) : x ∈ A এবং y = f(x)} কে তালিকা পদ্ধতিতে প্রকাশ কর এবং S এক-এক ফাংশন কি না যাচাই কর।","f⁻¹(x) নির্ণয় করে f⁻¹(5) এর মান বের কর এবং A ∩ f(A) এর শক্তি সেট নির্ণয় কর।"],
 "ক) f(−1) = −5, f(0) = −3, f(1) = −1, f(2) = 1 ⇒ f(A) = {−5, −3, −1, 1}\nখ) S = {(−1, −5), (0, −3), (1, −1), (2, 1)}\nভিন্ন ভিন্ন x এর জন্য y ভিন্ন ⇒ S একটি এক-এক ফাংশন\nগ) y = 2x − 3 ⇒ x = (y + 3)/2 ⇒ f⁻¹(x) = (x + 3)/2\nf⁻¹(5) = (5 + 3)/2 = 4\nA ∩ f(A) = {−1, 1} ⇒ শক্তি সেট = {∅, {−1}, {1}, {−1, 1}}",'মধ্যম'),
("50 জন শিক্ষার্থীর মধ্যে 30 জন গণিত, 25 জন বিজ্ঞান পছন্দ করে এবং 10 জন কোনোটিই পছন্দ করে না। M ও S যথাক্রমে গণিত ও বিজ্ঞান পছন্দকারীদের সেট।",
 ["n(M ∪ S) নির্ণয় কর।","n(M ∩ S), শুধু গণিত ও শুধু বিজ্ঞান পছন্দকারীর সংখ্যা নির্ণয় কর এবং ভেনচিত্রে দেখাও।","শুধু গণিত, শুধু বিজ্ঞান ও উভয় পছন্দকারীর সংখ্যাগুলো নিয়ে গঠিত সেট C হলে C কে তালিকা পদ্ধতিতে লেখ এবং R = {(x, y) ∈ C × C : x < y} নির্ণয় কর।"],
 "ক) n(M ∪ S) = 50 − 10 = 40\nখ) n(M ∩ S) = n(M) + n(S) − n(M ∪ S) = 30 + 25 − 40 = 15\nশুধু গণিত = 30 − 15 = 15, শুধু বিজ্ঞান = 25 − 15 = 10\nভেনচিত্র: শুধু M অংশে 15, ছেদ অংশে 15, শুধু S অংশে 10, বৃত্তের বাইরে 10\nগ) সংখ্যাগুলো 15, 10, 15; সেটে একই উপাদান একবার লেখা হয় ⇒ C = {10, 15}\nC × C = {(10, 10), (10, 15), (15, 10), (15, 15)}\nR = {(10, 15)}",'মধ্যম'),
("F(x) = (3x + 2)/(2x − 3), x ≠ 3/2 এবং A = {x ∈ ℤ : −2 ≤ x ≤ 2}।",
 ["F(0) ও F(1) এর মান নির্ণয় কর।","দেখাও যে, F(F(x)) = x","B = {F(x) : x ∈ A} কে তালিকা পদ্ধতিতে প্রকাশ কর এবং A ∩ B নির্ণয় কর।"],
 "ক) F(0) = 2/(−3) = −2/3; F(1) = 5/(−1) = −5\nখ) F(F(x)) এর লব = 3 · F(x) + 2 = (9x + 6 + 4x − 6)/(2x − 3) = 13x/(2x − 3)\nহর = 2 · F(x) − 3 = (6x + 4 − 6x + 9)/(2x − 3) = 13/(2x − 3)\n∴ F(F(x)) = 13x ÷ 13 = x\nগ) A = {−2, −1, 0, 1, 2}\nF(−2) = 4/7, F(−1) = 1/5, F(0) = −2/3, F(1) = −5, F(2) = 8\nB = {4/7, 1/5, −2/3, −5, 8}\nA ∩ B = ∅ (B এর কোনো উপাদান A তে নেই)",'কঠিন'),
("A = {x ∈ ℕ : 2 < x ≤ 6} এবং R = {(x, y) : x, y ∈ A এবং y = x + 1}।",
 ["A কে তালিকা পদ্ধতিতে প্রকাশ কর এবং n(A × A) নির্ণয় কর।","R কে তালিকা পদ্ধতিতে প্রকাশ কর এবং ডোম R ও রেঞ্জ R নির্ণয় কর।","ডোম R ∩ রেঞ্জ R এর শক্তি সেট নির্ণয় কর এবং R⁻¹ কে সেট গঠন পদ্ধতিতে প্রকাশ কর।"],
 "ক) A = {3, 4, 5, 6}; n(A × A) = 4 × 4 = 16\nখ) R = {(3, 4), (4, 5), (5, 6)}\nডোম R = {3, 4, 5}, রেঞ্জ R = {4, 5, 6}\nগ) ডোম R ∩ রেঞ্জ R = {4, 5}\nশক্তি সেট = {∅, {4}, {5}, {4, 5}}\nR⁻¹ = {(4, 3), (5, 4), (6, 5)} = {(x, y) : x, y ∈ A এবং y = x − 1}",'মধ্যম'),
("U = {1, 2, 3, …, 12}, A = {x ∈ U : x, 12 এর গুণনীয়ক}, B = {x ∈ U : x, 3 এর গুণিতক} এবং f(x) = x/3।",
 ["A ও B কে তালিকা পদ্ধতিতে প্রকাশ কর।","দেখাও যে, A ∖ B = A ∩ B′","f(B) নির্ণয় করে দেখাও যে, f(B) ⊆ A এবং B এর উপর f এক-এক ফাংশন।"],
 "ক) A = {1, 2, 3, 4, 6, 12}, B = {3, 6, 9, 12}\nখ) A ∖ B = {1, 2, 4}\nB′ = {1, 2, 4, 5, 7, 8, 10, 11} ⇒ A ∩ B′ = {1, 2, 4}\n∴ A ∖ B = A ∩ B′\nগ) f(3) = 1, f(6) = 2, f(9) = 3, f(12) = 4 ⇒ f(B) = {1, 2, 3, 4}\nf(B) এর প্রতিটি উপাদান A তে আছে ⇒ f(B) ⊆ A\nf(a) = f(b) ⇒ a/3 = b/3 ⇒ a = b ⇒ f এক-এক",'মধ্যম'),
("A = {−2, −1, 0, 1, 2} এবং S = {(x, y) : x ∈ A এবং y = x² + 1}।",
 ["S কে তালিকা পদ্ধতিতে প্রকাশ কর।","S এর ডোমেন ও রেঞ্জ নির্ণয় কর এবং S এক-এক ফাংশন কি না যাচাই কর।","B = রেঞ্জ S হলে (A ∩ B) × (A ∖ B) নির্ণয় কর।"],
 "ক) S = {(−2, 5), (−1, 2), (0, 1), (1, 2), (2, 5)}\nখ) ডোম S = {−2, −1, 0, 1, 2}, রেঞ্জ S = {1, 2, 5}\n(−1, 2) ও (1, 2) এ ভিন্ন x এর একই প্রতিচ্ছবি ⇒ S এক-এক নয় (তবে ফাংশন)\nগ) B = {1, 2, 5}\nA ∩ B = {1, 2}, A ∖ B = {−2, −1, 0}\n(A ∩ B) × (A ∖ B) = {(1, −2), (1, −1), (1, 0), (2, −2), (2, −1), (2, 0)}",'মধ্যম'),
("f(x) = x³ − 4x, A = {x ∈ ℝ : f(x) = 0} এবং B = {x ∈ ℤ : −1 ≤ x ≤ 1}।",
 ["A কে তালিকা পদ্ধতিতে প্রকাশ কর।","দেখাও যে, f(−x) = −f(x) এবং f(1) + f(−1) = 0","(A ∪ B) ∖ (A ∩ B) নির্ণয় কর এবং এর শক্তি সেটের উপাদান সংখ্যা নির্ণয় কর।"],
 "ক) x³ − 4x = x(x − 2)(x + 2) = 0 ⇒ A = {−2, 0, 2}\nখ) f(−x) = (−x)³ − 4(−x) = −x³ + 4x = −(x³ − 4x) = −f(x)\nf(1) = −3, f(−1) = 3 ⇒ f(1) + f(−1) = 0\nগ) B = {−1, 0, 1}\nA ∪ B = {−2, −1, 0, 1, 2}, A ∩ B = {0}\n(A ∪ B) ∖ (A ∩ B) = {−2, −1, 1, 2}\nশক্তি সেটের উপাদান সংখ্যা = 2⁴ = 16",'কঠিন'),
("f(x) = ax + b একটি ফাংশন, যেখানে f(1) = 5 এবং f(3) = 11।",
 ["a ও b এর মান নির্ণয় কর।","f⁻¹(x) নির্ণয় কর এবং f⁻¹(14) এর মান বের কর।","A = {x ∈ ℕ : f(x) < 20} এবং B = {f(x) : x ∈ A} হলে A, B, A ∩ B এবং n(A × B) নির্ণয় কর।"],
 "ক) a + b = 5, 3a + b = 11 ⇒ 2a = 6 ⇒ a = 3, b = 2 ⇒ f(x) = 3x + 2\nখ) y = 3x + 2 ⇒ x = (y − 2)/3 ⇒ f⁻¹(x) = (x − 2)/3\nf⁻¹(14) = 12/3 = 4\nগ) 3x + 2 < 20 ⇒ x < 6 ⇒ A = {1, 2, 3, 4, 5}\nB = {5, 8, 11, 14, 17}\nA ∩ B = {5}\nn(A × B) = 5 × 5 = 25",'কঠিন'),
]
ITEMS=[]
for i,(s_,p_,a_,lv) in enumerate(CQ):
    assert len(p_)==3 and a_.count('ক)')==1 and a_.count('খ)')==1 and a_.count('গ)')==1
    ITEMS.append({'n':f'b{11+i}','ex':'সমন্বিত','stem':s_,'p':p_,'a':a_,'lv':lv})
assert len(ITEMS)==10
